create table if not exists public.scores (id bigint generated by default as identity primary key,name text not null,grade text not null,team text not null,subject text not null default 'math',score integer not null,correct integer not null,student_id text not null default '',competition_code text not null default 'LIVRE',answers_json text not null default '[]',duration integer not null default 0,attempt_number integer not null default 1,integrity_status text not null default 'ok',integrity_notes text not null default '',achievements_json text not null default '[]',created_at timestamptz not null default now());
create table if not exists public.integration_settings (key text primary key,value text not null,updated_at timestamptz not null default now());
create table if not exists public.competitions (id bigint generated by default as identity primary key,name text not null,code text not null unique,active boolean not null default false,max_attempts integer not null default 1,scoring_rule text not null default 'best',starts_at timestamptz,ends_at timestamptz,live_status text not null default 'open',live_started_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.game_sessions (token text primary key,student_id text not null,name text not null,grade text not null,team text not null,competition_code text not null,started_at timestamptz not null,used boolean not null default false,device_id text not null default '',heartbeat_at timestamptz);
create table if not exists public.students (id bigint generated by default as identity primary key,student_id text not null unique,name text not null,grade text not null,team text not null,extra_time boolean not null default false,active boolean not null default true,created_at timestamptz not null default now());
create index if not exists scores_ranking_idx on public.scores(score desc,correct desc);
create index if not exists scores_student_round_idx on public.scores(student_id,competition_code);
create unique index if not exists one_active_competition on public.competitions(active) where active=true;
alter table public.scores enable row level security; alter table public.integration_settings enable row level security; alter table public.competitions enable row level security; alter table public.game_sessions enable row level security; alter table public.students enable row level security;
revoke all on public.scores,public.integration_settings,public.competitions,public.game_sessions,public.students from anon,authenticated;
